func TestDeDuplicate(t *testing.T) {
	input := []string{"go", "web", "go", "index", "web"}

	got := DeDuplicate(input)

	if len(got) != 3 {
		t.Fatalf("DeDuplicate() returned %d values, want 3: %v", len(got), got)
	}

	values := make(map[string]bool, len(got))
	for _, value := range got {
		values[value] = true
	}
	for _, want := range []string{"go", "web", "index"} {
		if !values[want] {
			t.Errorf("DeDuplicate() did not preserve %q: %v", want, got)
		}
	}
}

func TestDeDuplicateShortInput(t *testing.T) {
	input := []string{"only"}

	got := DeDuplicate(input)

	if len(got) != 1 || got[0] != "only" {
		t.Fatalf("DeDuplicate() = %v, want %v", got, input)
	}
}

func TestConvertToWebsiteResolvesLinksAndIncrementsDepth(t *testing.T) {
	source := models.Website{Link: "https://example.com/docs/index.html", Depth: 2}
	links := []string{"../about", "/contact", "https://other.example/page"}

	got, err := ConvertToWebsite(links, source)
	if err != nil {
		t.Fatalf("ConvertToWebsite() returned unexpected error: %v", err)
	}

	want := []string{
		"https://example.com/about",
		"https://example.com/contact",
		"https://other.example/page",
	}
	if len(got) != len(want) {
		t.Fatalf("ConvertToWebsite() returned %d websites, want %d", len(got), len(want))
	}
	for i, website := range got {
		if website.Link != want[i] {
			t.Errorf("ConvertToWebsite()[%d].Link = %q, want %q", i, website.Link, want[i])
		}
		if website.Depth != source.Depth+1 {
			t.Errorf("ConvertToWebsite()[%d].Depth = %d, want %d", i, website.Depth, source.Depth+1)
		}
	}
}

func TestConvertToWebsiteRejectsInvalidSourceURL(t *testing.T) {
	_, err := ConvertToWebsite([]string{"https://example.com"}, models.Website{Link: "%"})
	if err == nil {
		t.Fatal("ConvertToWebsite() returned nil error for invalid source URL")
	}
}

func TestExtractLinks(t *testing.T) {
	root := parseHTML(t, `<main><a href="/one">one</a><p><a href="https://example.com/two">two</a></p></main>`)

	got := ExtractLinks(root, 0)

	want := []string{"/one", "https://example.com/two"}
	if len(got) != len(want) {
		t.Fatalf("ExtractLinks() returned %d links, want %d: %v", len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("ExtractLinks()[%d] = %q, want %q", i, got[i], want[i])
		}
	}
}

