func parseHTML(t *testing.T, source string) *html.Node {
	t.Helper()

	root, err := html.Parse(strings.NewReader(source))
	if err != nil {
		t.Fatalf("html.Parse() returned unexpected error: %v", err)
	}
	return root
}
